const AppConfig = require("../../../../../libs/custom-mongo-storage-plugin/appConfig");
const FlowConfig = require("../../../../../libs/custom-mongo-storage-plugin/flows");
const multer = require('multer');
const unzipper = require('unzipper');
const { v4: uuidv4 } = require('uuid');
const path = require('path');
const archiver = require('archiver');
const fs = require('fs');
const { runTransaction } = require("../../../../../libs/custom-mongo-storage-plugin/utils");
var apiUtils = require("../util");
const MAX_UNZIPPED_SIZE = 50 * 1024 * 1024;

class ApplicationError extends Error {
    constructor(status, message) {
        super(message);
        this.name = 'ApplicationError';
        this.status = status;
    }
}



async function validateRequestBody(reqBody, requiredFields) {
    if (!reqBody) {
        throw new ApplicationError(400, 'Request body is required');
    }
    for (const field of requiredFields) {
        if (!reqBody[field]) {
            throw new ApplicationError(400, `${field} is required`); 
        }
    }
    return reqBody;
}

/**
 * Removes specified fields from an object
 * @param {Object} doc - The document to clean
 * @param {Array<string>} fieldsToRemove - Array of field names to remove
 * @returns {Object} Cleaned object
 */
function cleanDocument(doc, fieldsToRemove) {
    const cleanedDoc = doc.toObject ? doc.toObject() : { ...doc };
    fieldsToRemove.forEach(field => {
        delete cleanedDoc[field];
    });
    return cleanedDoc;
}

const storage = multer.diskStorage({
    destination: function (req, file, cb) {
        cb(null, '/tmp/'); // Ensure this directory exists
    },
    filename: function (req, file, cb) {
        cb(null, `${Date.now()}-${path.basename(file.originalname)}`);
    }
});

const upload = multer({
    storage: storage,
    limits: {
        fileSize: 10 * 1024 * 1024 // 10MB limit
    },
    fileFilter: function (req, file, cb) {
        if (file.mimetype !== 'application/zip' && file.mimetype !== 'application/x-zip-compressed') {
            return cb(new ApplicationError(400, 'Only ZIP files are allowed'));
        }
        cb(null, true);
    }
}).single('archive');

async function generateUniqueAppId() {
    let appId;
    let isUnique = false;
    while (!isUnique) {
        appId = uuidv4();
        const existingApp = await AppConfig.findOne({ appId });
        if (!existingApp) {
            isUnique = true;
        }
    }
    return appId;
}

async function generateUniqueAppSecret() {
    return uuidv4();
}

/**
 * Processes flow files to update IDs and relationships
 * @param {Array} flowFiles - Array of flow files to process
 * @param {string} accountId - Account ID
 * @param {string} appId - Application ID
 * @param {string} username - Username of the person creating the flows
 * @returns {Array} Processed flows ready for import
 */
async function processFlowFiles(flowFiles, accountId, appId, username) {
    const flows = [];
    const idMapping = new Map();

    for (const flowFile of flowFiles) {
        const flowContent = await flowFile.buffer();
        const flowData = JSON.parse(flowContent.toString());
        flows.push(flowData);
    }

    const tabNodes = flows.filter(flow => flow.type === 'tab');
    for (const tabNode of tabNodes) {
        const oldId = tabNode.id;
        const newId = uuidv4();
        idMapping.set(oldId, newId);
        tabNode.id = newId;

        flows.forEach(flow => {
            if (flow.z === oldId) {
                flow.z = newId;
            }
        });
    }

    const nonTabNodes = flows.filter(flow => flow.type !== 'tab');
    for (const node of nonTabNodes) {
        const oldId = node.id;
        const newId = uuidv4();
        idMapping.set(oldId, newId);
        node.id = newId;
    }

    for (const flow of flows) {
        if (flow.wires) {
            flow.wires = flow.wires.map(wireArray => 
                wireArray.map(wire => idMapping.get(wire) || wire)
            );
        }
    }

    return flows.map(flow => ({
        ...flow,
        accountId,
        appId,
        createdBy: username
    }));
}

module.exports = {
    init: function(_runtimeAPI) {
        runtimeAPI = _runtimeAPI;
    },
 
    
    /**
     * Exports all flows and the app configuration associated with a specific app as a ZIP archive.
     * The archive includes:
     * - app.json: Contains the app configuration
     * - flows/: Directory containing individual flow files
     * - metadata.json: Export information including timestamp and user
     */
    export: async function (req, res) {
        try {
            const appId = req.params.appId;

            if (!appId) {
                throw new ApplicationError(400, 'App ID is required');
            }

            const app = await AppConfig.findOne({ appId, accountId });
            if (!app) {
                throw new ApplicationError(404, 'App not found');
            }

            const flows = await FlowConfig.find({ accountId, appId }).exec();
            if (!flows || flows.length === 0) {
                throw new ApplicationError(404, 'No flows found for this app');
            }

            res.setHeader('Content-Type', 'application/zip');
            res.setHeader('Content-Disposition', `attachment; filename=${appId}-flows-export.zip`);

            const archive = archiver('zip', { zlib: { level: 9 } });
            archive.pipe(res);

            const appFieldsToRemove = ['_id', 'accountId', 'createdAt', 'updatedAt', 'createdBy', 'updatedBy'];
            const cleanedApp = cleanDocument(app, appFieldsToRemove);
            archive.append(JSON.stringify(cleanedApp, null, 2), { name: 'app.json' });

            const flowFieldsToRemove = ['_id', 'accountId', 'createdBy', 'appId'];
            flows.forEach(flow => {
                const cleanedFlow = cleanDocument(flow, flowFieldsToRemove);
                archive.append(JSON.stringify(cleanedFlow, null, 2), {
                    name: `flows/${flow._id}.json`
                });
            });

            const metadata = {
                exportedAt: new Date().toISOString(),
                appId: appId,
                accountId: accountId,
                exportedBy: req.user.username
            };
            archive.append(JSON.stringify(metadata, null, 2), { name: 'metadata.json' });
            archive.on('error', (err) => {
                throw new ApplicationError(500, `Archive creation failed: ${err.message}`);
            });
            res.on('error', (err) => {
                throw new ApplicationError(500, `Response stream error: ${err.message}`);
            });
            await archive.finalize();
        } catch (error) {
            if (!res.headersSent) {
                res.status(error.status || 500).json({ message: error.message });
            } else {
                res.end();
            }
        }
    },
    /**
     * Imports flows and app configuration from a ZIP archive.
     * The archive should contain:
     * - app.json: App configuration that will be imported
     * - flows/: Directory containing flow files to be imported
     * - metadata.json: (Optional) Export information
     * 
     * If the imported app ID already exists, a new unique ID - secret pairwill be generated.
     * All imported flows will be associated with the new app ID and account.
     */
    import: async function (req, res) {
        try {
            await new Promise((resolve, reject) => {
                upload(req, res, function (err) {
                    if (err instanceof multer.MulterError) {
                        reject(new ApplicationError(400, `File upload error: ${err.message}`));
                    } else if (err) {
                        reject(err);
                    }
                    resolve();
                });
            });

            const accountId = await validateAccountId(req.user);
            if (!req.file) {
                throw new ApplicationError(400, 'No file uploaded');
            }

            let directory;
            try {
                directory = await unzipper.Open.file(req.file.path);
            } catch (unzipError) {
                throw new ApplicationError(400, 'Failed to unzip file. Please ensure the ZIP file is not corrupted');
            }

            const totalSize = directory.files.reduce((sum, file) => sum + file.uncompressedSize, 0);
            if (totalSize > MAX_UNZIPPED_SIZE) {
                throw new ApplicationError(400, 'Unzipped content exceeds size limit');
            }

            const appFile = directory.files.find(f => f.path === 'app.json');
            if (!appFile) {
                throw new ApplicationError(400, 'Invalid archive: app.json not found');
            }

            const appContent = await appFile.buffer();
            const appData = JSON.parse(appContent.toString());
            
            const result = await runTransaction(async (session) => {
                const existingApp = await AppConfig.findOne({ appId: appData.appId }).session(session);
                if (existingApp) {
                    appData.appId = await generateUniqueAppId();
                    appData.appSecret = await generateUniqueAppSecret();
                } else if (!appData.appSecret) {
                    appData.appSecret = await generateUniqueAppSecret();
                }

                const newApp = {
                    ...appData,
                    accountId,
                    createdBy: req.user.username,
                    updatedBy: req.user.username,
                    createdAt: Date.now(),
                    updatedAt: Date.now()
                };
                await AppConfig.create([newApp], { session });

                const flowFiles = directory.files.filter(f => f.path.startsWith('flows/'));
                const processedFlows = await processFlowFiles(
                    flowFiles,
                    accountId,
                    newApp.appId,
                    req.user.username
                );
                await FlowConfig.insertMany(processedFlows, { session });

                return { newAppId: newApp.appId };
            });

            await fs.promises.unlink(req.file.path);
            res.status(200).json({
                message: 'App and Flows imported successfully',
                newAppId: result.newAppId
            });
        } catch (error) {
            if (req.file) {
                try {
                    await fs.promises.unlink(req.file.path);
                } catch (unlinkError) {
                    console.error('Failed to clean up temporary file:', unlinkError);
                }
            }
            console.error('Import Flows Error:', error);
            res.status(error.status || 500).json({
                message: error.message || 'Failed to import flows',
            });
        }
    },
    getMaskId: async function (req, res) {
        const appId = req.params.appId;
        const maskId = await await runtimeAPI.storage.getMaskId(appId);
        return res.json({ success: true, data: maskId })
    }
}